'use strict';
const Guide=RestorationGuide;
let guideSled='early',guideStepId='',guideErrors=[],guideMapOpen=false;
function guideState(){state.guides=Guide.migrate(state.guides,state);return state.guides;}
function guideRecord(sled,id){const record=guideState().sleds[sled].steps[id];if(record)return record;const data={};if(id==='evidence')Object.assign(data,sled==='early'?{overall:'photo-front',enginePhoto:'photo-motor'}:{overall:'photo-eight-porch',plateDisposition:'Plate / markings photographed',platePhoto:'photo-eight-plate'});if(id==='chassis'&&sled==='eight')Object.assign(data,{year:'1968',model:'Super Olympique E',code:'3E8-131356',conclusion:'Unresolved — more research needed'});if(id==='engine'&&sled==='early')Object.assign(data,{serial:'1308696',displacement:'247 cc on engine tag',photo:'photo-motor'});return{status:'draft',data,blocker:'',updated:''};}
function recordedChassis(sled){guideState();return Guide.isDone(Guide.steps.find(s=>s.id==='chassis'),state,sled)?guideRecord(sled,'chassis').data:null;}
function guideSledTitle(sled){const chassis=recordedChassis(sled);if(chassis)return chassis.year+' '+chassis.model;const starting=guideRecord(sled,'intake').data;return ((starting.year||'Year unknown')+' '+(starting.model||'Ski-Doo')).toUpperCase();}
function guideIdentityCaption(sled){const chassis=recordedChassis(sled);return chassis?'Chassis identity recorded in the walkthrough':sled==='early'?'Early single-track · exact model unknown':'300 E · chassis code review open';}
function guideIdentityBadge(sled){return recordedChassis(sled)?'Identity recorded':sled==='early'?'Year unconfirmed':'Plate photographed';}
function guideProfileSpecs(sled){const chassis=recordedChassis(sled);return chassis?[['Recorded chassis year',chassis.year],['Recorded chassis model',chassis.model],['Chassis identifier',chassis.code],['Identity source',chassis.reference],['Supporting findings',chassis.reasoning],['Installed engine',guideRecord(sled,'engine').data.type||'Discovery still open']]:null;}
function guideSledPrompt(sled){guideState();const info=Guide.summary(state,sled),record=info.next?guideRecord(sled,info.next.id):null;return `<article class="guide-prompt"><div><span class="eyebrow">${esc(NAMES[sled])} / ${info.phase?esc(info.phase.title):'PROJECT CLOSED'}</span><h3>${info.next?esc(info.next.title):'Restoration record complete'}</h3><p>${record?.status==='blocked'?'Needs attention: '+esc(record.blocker):info.next?esc(info.next.summary):'All recorded stages are complete. Review or reopen a step whenever the findings change.'}</p><p class="identity-caption">${recordedChassis(sled)?'Chassis identity recorded':'Working identity only · verify year & model before ordering'}</p><span class="guide-progress-caption">${info.done} / ${info.total} steps complete · ${info.percent}%</span></div><button class="button dark small" data-guide-sled="${sled}">${info.next?'Continue walkthrough':'Review walkthrough'} ↗</button></article>`}
function guideIdentityFile(sled){
 const intake=guideRecord(sled,'intake'),chassis=recordedChassis(sled),photos=state.photos.filter(p=>p.sled===sled),ready=Guide.isDone(Guide.steps.find(s=>s.id==='intake'),state,sled);
 return `<section class="identity-file" aria-label="Starting identity file"><div class="section-head"><div><span class="eyebrow muted">STEP 01 / YOUR STARTING FILE</span><h3>The estimate and photos are here.</h3></div><span class="badge ${ready?'green':'amber'}">${ready?'Starting file ready':'Starting file needs review'}</span></div><div class="identity-facts"><div><small>WORKING CHASSIS YEAR</small><b>${esc(intake.data.year||'Unknown')}</b></div><div><small>WORKING MODEL</small><b>${esc(intake.data.model||'Unknown')}</b></div><div><small>CHASSIS VERIFICATION</small><b>${chassis?'Year & model recorded':'Still unconfirmed'}</b></div></div><p>A starting estimate helps organize the file. It does not establish the chassis year. Verify the chassis separately from the installed engine.</p><div class="identity-photos">${photos.slice(0,6).map(p=>`<button type="button" data-photo="${esc(p.id)}" aria-label="View ${esc(p.title)}"><img src="${esc(p.src)}" alt="${esc(p.title)}" loading="lazy"><span>${esc(p.title)}</span></button>`).join('')}</div><div class="identity-file-actions"><span>${photos.length} photo${photos.length===1?'':'s'} already in this file</span><button type="button" class="text-button" data-guide-step="intake">Review starting year & photo ↗</button><button type="button" class="text-button" data-nav="archive">All photos & manuals ↗</button></div>${guideOrderingStatus(sled)}</section>`;
}
function guideOrderingStatus(sled){
 const missing=Guide.steps.filter(s=>s.phase==='discovery'&&!Guide.isDone(s,state,sled)),chassis=recordedChassis(sled);
 return `<div class="identity-order-state"><b>${missing.length?'Ordering locked':'Discovery recorded · check each part’s fitment'}</b><p>${!chassis?'Verify the chassis year and model before ordering. ':''}${missing.length?'Still open: '+missing.map(s=>esc(s.title)).join('; ')+'.':'The installed equipment and references are recorded. Every new order still needs its own verified specification and supplier link.'}</p><button type="button" class="text-button" data-guide-sled="${sled}">${missing.length?'Continue identification':'Review discovery'} ↗</button></div>`;
}
function guideChassisReferences(sled){
 return `<section class="identity-checklist guide-source-card"><h4>Check the factory sources</h4><p>${sled==='early'?'Start with the early chassis diagrams. Record matching details and any conflicts; the engine comparison chart cannot confirm the chassis year.':'Open the supplied chassis plate at full size and check every character, including S versus 3. Record the reading before comparing it with the model-code table.'}</p><div class="guide-reference-links"><a href="${sled==='early'?sourceEarly:source68}" target="_blank" rel="noopener">${sled==='early'?'Early factory parts reference':'1968 factory parts reference'} ↗</a><a href="${sourceCodes}#page=17" target="_blank" rel="noopener">Factory model-code reference ↗</a></div></section>`;
}
const guideShortTitles={intake:'Starting file',evidence:'Photo evidence',chassis:'Chassis year & model',engine:'Installed engine',carburetor:'Carburetor stamping',drive:'Drive & electrical',references:'Factory documents'};
const guidePhotoHints={overall:'Show the whole sled, including the hood and track.',dashboard:'Show the controls and the area behind the windshield.',enginePhoto:'Get close enough to read the engine tag.',platePhoto:'Capture every character on the chassis plate or stamping.',photo:'Choose a clear photo that supports this finding.',drivePhoto:'Show the clutch assemblies and their markings.',finishedPhoto:'Choose a photo of the finished sled.'};
function guidePhotoPreview(field,value,sled){
 const photo=state.photos.find(p=>p.id===value&&p.sled===sled);
 return photo?`<a href="#photo-${esc(photo.id)}" class="guide-photo-preview" data-photo="${esc(photo.id)}" aria-label="View ${esc(photo.title)}"><img src="${esc(photo.src)}" alt="${esc(photo.title)}"><span>View full photo ↗</span></a>`:`<div class="guide-photo-empty"><span aria-hidden="true">＋</span><b>No photo selected</b><p>${esc(guidePhotoHints[field.id]||guidePhotoHints.photo)}</p></div>`;
}
function guideField(field,data,sled){
 const value=data[field.id]??'',id='g-'+field.id,helpId=id+'-hint';let control;
 if(field.type==='photo'){
  const photos=state.photos.filter(p=>p.sled===sled);
  control=`<div data-guide-preview="${field.id}">${guidePhotoPreview(field,value,sled)}</div><div class="guide-photo-select"><select id="${id}" name="${field.id}" data-guide-field aria-describedby="${helpId}"><option value="">Select a photo from this sled…</option>${photos.map(p=>option(p.id,p.title,value)).join('')}</select><button type="button" class="text-button" data-guide-upload="${sled}">+ Upload a photo</button></div><small id="${helpId}" class="guide-field-hint">${esc(guidePhotoHints[field.id]||guidePhotoHints.photo)}</small>`;
 }else if(field.type==='select')control=`<select id="${id}" name="${field.id}" data-guide-field><option value="">Choose an answer…</option>${field.options.map(x=>option(x,x,value)).join('')}</select>`;
 else if(field.type==='textarea')control=`<textarea id="${id}" name="${field.id}" data-guide-field rows="3" maxlength="20000">${esc(value)}</textarea>`;
 else if(field.type==='check')control=`<label class="guide-check" for="${id}"><input id="${id}" type="checkbox" name="${field.id}" data-guide-field${value===true?' checked':''}><span>${esc(field.label)}</span></label>`;
 else control=`<input id="${id}" name="${field.id}" data-guide-field type="${field.type}" value="${esc(value)}"${field.type==='number'?` min="${field.min}" max="${field.max}" step="1"`:''} maxlength="20000">`;
 return `<div class="field guide-field${field.type==='photo'?' guide-photo-field':''}"${field.when?` data-guide-when="${esc(field.when[0])}" data-guide-equals="${esc(field.when[1])}"`:''}${Guide.visible(field,data)?'':' hidden'}>${field.type==='check'?'':`<label for="${id}">${esc(field.label)}</label>`}${control}</div>`;
}
function guideFieldGroups(step,record,sled){
 const fields=ids=>ids.map(id=>guideField(step.fields.find(f=>f.id===id),record.data,sled)).join('');
 if(step.id==='evidence')return `<div class="guide-photo-grid">${fields(['overall','dashboard','enginePhoto'])}<section class="guide-identifier"><div class="guide-card-heading"><span class="eyebrow muted">CHASSIS EVIDENCE</span><h3>Look for the identifier.</h3><p>A missing plate is a finding, too. Record where you looked.</p></div>${fields(['plateDisposition','platePhoto','plateSearch'])}</section></div>`;
 if(step.id==='chassis')return `<section class="guide-field-group"><div class="guide-group-label"><span>01</span><div><h3>Read the sled.</h3><p>Start with the actual markings and supporting photo.</p></div></div>${fields(['photo','code'])}</section><section class="guide-field-group"><div class="guide-group-label"><span>02</span><div><h3>Connect the evidence.</h3><p>Explain the match using a factory source or named expert.</p></div></div>${guideChassisReferences(sled)}${fields(['method','reference','reasoning'])}</section><section class="guide-field-group"><div class="guide-group-label"><span>03</span><div><h3>Record your conclusion.</h3><p>Keep it unresolved until the evidence supports the year and model.</p></div></div>${fields(['year','model','conclusion'])}</section>`;
 return `<div class="guide-fields">${step.fields.map(f=>guideField(f,record.data,sled)).join('')}</div>`;
}
function guideSledPicker(){return `<div class="guide-sled-picker" role="group" aria-label="Choose a sled">${['early','eight'].map((sled,i)=>{
 const intake=guideRecord(sled,'intake').data,photo=state.photos.find(p=>p.id===intake.overall&&p.sled===sled)||state.photos.find(p=>p.sled===sled),active=sled===guideSled;
 return `<button class="guide-sled-choice${active?' selected':''}" data-guide-sled="${sled}" aria-pressed="${active}">${photo?`<img src="${esc(photo.src)}" alt="">`:'<span class="guide-sled-no-photo">◇</span>'}<span><small>PROJECT 0${i+1}</small><b>${esc(sled==='early'?'The early Ski-Doo':'The Olympique')}</b><em>${esc(recordedChassis(sled)?guideSledTitle(sled):(intake.year||'Year unknown')+' · '+(sled==='early'?'Year unconfirmed':'Identity under review'))}</em></span><span class="guide-sled-selected" aria-hidden="true">${active?'✓':'→'}</span></button>`;
 }).join('')}</div>`;}
function guideJourney(step,info){return `<aside class="guide-journey" aria-label="Restoration journey" data-expanded="${guideMapOpen}"><button type="button" class="guide-map-toggle" data-guide-map aria-expanded="${guideMapOpen}" aria-controls="guide-journey-body"><span>Journey map <small>${esc(Guide.phases.find(p=>p.id===step.phase).title)}</small></span><span aria-hidden="true">${guideMapOpen?'−':'＋'}</span></button><div id="guide-journey-body"><div class="guide-journey-heading"><span class="eyebrow muted">THE JOURNEY</span><span id="guide-journey-progress">${info.done}/${info.total}</span></div>${Guide.phases.map((phase,i)=>{
 const members=Guide.steps.filter(s=>s.phase===phase.id),done=members.filter(s=>Guide.isDone(s,state,guideSled)).length,selected=phase.id===step.phase,complete=done===members.length;
 return `<details data-guide-phase="${phase.id}" class="guide-phase${selected?' current':''}${complete?' complete':''}"${selected?' open':''}><summary><span class="guide-phase-number">${complete?'✓':String(i+1).padStart(2,'0')}</span><span><b>${esc(phase.title)}</b><small>${done} of ${members.length} complete</small></span><span class="guide-phase-chevron" aria-hidden="true">⌄</span></summary><div class="guide-journey-steps">${members.map(s=>{
 const status=guideStepStatus(s,guideSled),active=s.id===step.id,isDone=Guide.isDone(s,state,guideSled);
 return `<button type="button" data-guide-step="${s.id}" class="${active?'selected ':''}${isDone?'done':''}"${active?' aria-current="step"':''}><span class="guide-step-dot" aria-hidden="true">${isDone?'✓':status==='Locked'?'·':Guide.steps.indexOf(s)+1}</span><span><b>${esc(guideShortTitles[s.id]||s.title)}</b><small>${status}</small></span>${active?'<span class="guide-here" aria-hidden="true">←</span>':''}</button>`;
 }).join('')}</div></details>`;
 }).join('')}<p class="guide-journey-foot">One finding at a time.<br>Partial progress is welcome here.</p></div></aside>`;}
function guideTaskProgress(step,record){
 const fields=step.fields.filter(f=>Guide.visible(f,record.data)),issues=Guide.issues(step,record,state,guideSled),missing=new Set(issues.filter(e=>e.field).map(e=>e.field)),done=fields.filter(f=>!missing.has(f.id)).length;
 return `<span>${done} of ${fields.length} findings recorded</span><div class="guide-task-track" aria-hidden="true">${fields.map(f=>`<i class="${missing.has(f.id)?'':'filled'}"></i>`).join('')}</div>`;
}
function guideParts(step,sled){let list;if(step.category)list=state.parts.filter(p=>p.sled===sled&&p.category===step.category);else if(['parts-plan','repairs'].includes(step.id))list=Guide.requiredParts(state,sled);else return'';return `<section class="guide-parts"><div class="section-head"><h4>Linked parts & work items</h4><button type="button" data-sled-parts="${sled}">Full tracker ↗</button></div>${list.length?list.map(p=>`<div class="guide-part-row"><div><b>${esc(p.name)}</b><small>${esc(p.status)} · ${p.number?esc(p.number):'Specification not recorded'}</small></div><button type="button" class="button secondary small" data-edit-part="${esc(p.id)}">Edit</button></div>`).join(''):'<p class="mini-note">No applicable items remain. Record why any items were retained or deferred in your findings.</p>'}</section>`;}
function guideStepStatus(step,sled){if(Guide.isDone(step,state,sled))return step.id==='intake'?'Starting file ready':'Complete';if(Guide.blockers(step,state,sled).length)return'Locked';const record=guideRecord(sled,step.id);if(record.status==='blocked')return'Needs help';if(record.status==='complete')return'Recheck required';return record.updated?'In progress':'To do';}
function guideView(){
 guideState();const info=Guide.summary(state,guideSled);let step=Guide.steps.find(s=>s.id===guideStepId);if(!step)step=info.next||Guide.steps[0];guideStepId=step.id;
 const phase=Guide.phases.find(p=>p.id===step.phase),record=guideRecord(guideSled,step.id),blocked=Guide.blockers(step,state,guideSled),effective=Guide.isDone(step,state,guideSled),index=Guide.steps.indexOf(step),previous=Guide.steps[index-1],following=Guide.steps[index+1],editable=canEdit(),chassis=recordedChassis(guideSled),intake=guideRecord(guideSled,'intake').data;
 return `<div class="restoration-guide"><header class="guide-page-heading"><div><a class="guide-home-link" href="#overview" data-nav="overview">← Home</a><h1>Restoration walkthrough</h1><p>Choose a sled to see its next step. Record photos and findings as you work from identification through repair.</p></div></header>${guideSledPicker()}<div class="guide-project-strip"><div class="guide-identity-note"><span class="guide-status-dot ${chassis?'verified':''}" aria-hidden="true"></span><span>${chassis?'Chassis identity recorded':`Working year: <b>${esc(intake.year||'Unknown')}</b> · ${guideSled==='early'?'chassis year unconfirmed':'chassis verification open'}`}</span></div><span id="guide-overall-progress">${info.done} of ${info.total} steps complete</span></div><div class="guide-layout">${guideJourney(step,info)}<section class="guide-content"><article class="guide-workbench" id="guide-workbench"><header class="guide-task-heading"><div class="section-head"><span class="eyebrow muted">${esc(phase.title)} <span class="guide-slash">/</span> STEP ${String(index+1).padStart(2,'0')}</span><span id="guide-step-status" class="badge ${effective?'green':blocked.length?'gray':'amber'}">${guideStepStatus(step,guideSled)}</span></div><h2 id="guide-task-title" tabindex="-1">${esc(step.title)}</h2><p class="guide-summary">${esc(step.summary)}</p>${!blocked.length?`<div class="guide-task-progress" id="guide-task-progress" aria-live="polite">${guideTaskProgress(step,record)}</div>`:''}</header>${blocked.length?`<div class="guide-waiting"><span class="guide-waiting-icon" aria-hidden="true">↳</span><div><h3>A few findings come first.</h3><p>This step is waiting on earlier findings. Your previous entries remain saved.</p><button type="button" class="button" data-guide-step="${blocked[0].id}">Continue with ${esc(guideShortTitles[blocked[0].id]||blocked[0].title)} →</button><details><summary>See all ${blocked.length} prerequisites</summary><ul>${blocked.map(s=>`<li><button type="button" class="text-button" data-guide-step="${s.id}">${esc(s.title)} →</button></li>`).join('')}</ul></details></div></div>`:''}${!editable?`<div class="guide-reader-note"><span aria-hidden="true">◉</span> ${isDesignPreview()?'This design preview is read only. Open the live garage to update findings.':'You’re viewing Joshua’s restoration record. Findings can be updated after owner sign-in.'}</div>`:''}${record.status==='blocked'&&record.blocker?`<div class="guide-open-issue"><span class="eyebrow">OPEN QUESTION</span><p>${esc(record.blocker)}</p></div>`:''}${record.status==='complete'&&!effective&&!blocked.length?'<div class="banner"><b>This step needs another look.</b>A required field, photo or part status has changed. Review the findings, then complete it again.</div>':''}<div class="guide-task-body"><details class="guide-howto"><summary><span>How to approach this step</span><span aria-hidden="true">＋</span></summary><ol class="guide-instructions">${step.instructions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><div id="guide-errors" role="alert" tabindex="-1">${guideErrorHTML(guideErrors)}</div><form id="guide-form" novalidate data-guide-id="${step.id}" data-guide-sled="${guideSled}"><fieldset${blocked.length||!editable?' disabled':''}><legend class="visually-hidden">${esc(step.title)} findings</legend>${step.id==='evidence'?'<p class="guide-form-intro">Select the matching views. We’ve kept the photos you already supplied.</p>':step.id==='intake'?'<p class="guide-form-intro">Already filled from your supplied photos and research. An estimate is a starting point; chassis verification comes later.</p>':'<p class="guide-form-intro">Record what you know. You can leave gaps and come back.</p>'}${guideFieldGroups(step,record,guideSled)}${guideParts(step,guideSled)}<details class="guide-help"${record.status==='blocked'?' open':''}><summary>Not sure yet? Leave yourself a question.</summary><p>A missing number or conflicting source is a useful finding. Keep the step open until it’s resolved.</p><div class="field"><label for="guide-blocker">What do you need to find out?</label><textarea id="guide-blocker" name="blocker" maxlength="10000" rows="3" placeholder="e.g. Need a clearer photo of the chassis stamping…">${esc(record.blocker)}</textarea></div><button type="button" class="button secondary small" data-guide-action="blocked">Save question & keep open</button></details><div class="guide-form-actions"><div class="guide-save-copy"><span class="guide-draft-dot" aria-hidden="true"></span><p id="guide-save-state" role="status">${record.updated?'Saved '+esc(new Date(record.updated).toLocaleString()):editable?'Partial findings save as you go.':'Published record · read only'}</p></div><button type="button" class="button secondary" data-guide-action="draft">Save draft</button><button type="submit" class="button">${effective?'Confirm & continue':'Complete step'} →</button></div></fieldset></form>${!blocked.length?`<p id="guide-completion-note" class="guide-completion-note">${effective?'✓ This step is recorded complete. Changing a finding reopens it for review.':'Completing a step checks the required findings. Saving a draft keeps it open.'}</p>`:''}</div></article><div class="guide-step-footer">${previous?`<button type="button" class="text-button" data-guide-step="${previous.id}">← ${esc(guideShortTitles[previous.id]||previous.title)}</button>`:'<span>Every restoration starts with a story.</span>'}${following?`<span>UP NEXT <b>${esc(guideShortTitles[following.id]||following.title)}</b></span>`:'<span>The end of the trail. A new chapter begins.</span>'}</div><details class="guide-file-drawer"><summary><span>Your sled’s starting file <small>${state.photos.filter(p=>p.sled===guideSled).length} photos · estimate & research</small></span><span aria-hidden="true">＋</span></summary>${guideIdentityFile(guideSled)}</details><div class="guide-resource-footer"><span>Keep the evidence close.</span><button class="text-button" data-nav="archive">Photos & factory references ↗</button><button class="text-button" data-sled-parts="${guideSled}">Parts tracker ↗</button><button class="text-button" data-action="backup">Export backup ↗</button></div></section></div></div>`;
}
function guideErrorHTML(errors){return errors.length?`<div class="guide-errors"><b>This step is still open.</b><ul>${errors.map(e=>`<li>${esc(e.message)}${e.field?` <button type="button" class="text-button" data-guide-focus="${esc(e.field)}">Go to finding →</button>`:''}${e.part?` <button type="button" class="text-button" data-edit-part="${esc(e.part)}">Edit item ↗</button>`:e.step?` <button class="text-button" data-guide-step="${esc(e.step)}">Open step ↗</button>`:''}</li>`).join('')}</ul></div>`:'';}
function guideFormData(){const form=document.querySelector('#guide-form');if(!form)return null;const step=Guide.steps.find(s=>s.id===form.dataset.guideId);if(!step)return null;const values=new FormData(form),data={};for(const f of step.fields)data[f.id]=f.type==='check'?values.has(f.id):String(values.get(f.id)||'').trim();return{form,step,sled:form.dataset.guideSled,data,blocker:String(values.get('blocker')||'').trim()};}
function saveGuide(action='draft',silent=false){if(!requireEditor())return false;const found=guideFormData();if(!found)return false;const previous=JSON.stringify(state.guides);const result=Guide.save(state,found.sled,found.step.id,found.data,action,found.blocker);if(!result.ok){if(!silent){guideErrors=result.errors;const box=document.querySelector('#guide-errors');box.innerHTML=guideErrorHTML(guideErrors);for(const field of found.step.fields){const input=document.querySelector('#g-'+field.id);if(input){if(guideErrors.some(e=>e.field===field.id))input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');}}box.focus();toast('The step is still open. Resolve the listed requirements.');}return false;}
 if(!persist()){state.guides=JSON.parse(previous);return false;}
 if(!silent){if(action==='complete'){state.logs.push({id:uid(),sled:found.sled,date:today(),title:'Guide: '+found.step.title,body:'Completed '+found.step.phase+' step.\n'+found.step.fields.filter(f=>Guide.visible(f,found.data)).map(f=>f.label+': '+(f.type==='photo'?(state.photos.find(p=>p.id===found.data[f.id])?.title||'Photo unavailable'):f.type==='check'?'Confirmed':found.data[f.id])).join('\n')});persist();guideStepId=result.next?.id||found.step.id;toast(result.next?'Step recorded. Here is your next action.':'All restoration stages are recorded complete.');}else toast(action==='blocked'?'Issue queued for publishing. This step remains open.':'Draft queued for publishing. This step remains open.');guideErrors=[];render('guide');if(action==='complete')focusGuideTask();}else refreshGuideSaveState();return true;}
function refreshGuideSaveState(){
 const status=document.querySelector('#guide-save-state');if(!status)return;
 status.textContent=!canEdit()?'Published record · read only':garageSync.status==='saving'?'Draft saved · publishing changes…':garageSync.status==='published'?'All changes published.':garageSync.message?'Publishing paused. Keep or export your draft.':'Partial findings save as you go.';
}
function refreshGuideProgress(step,sled){
 const info=Guide.summary(state,sled),badge=document.querySelector('#guide-step-status');
 if(badge){badge.textContent=guideStepStatus(step,sled);badge.className='badge '+(Guide.isDone(step,state,sled)?'green':'amber');}
 const overall=document.querySelector('#guide-overall-progress');if(overall)overall.textContent=info.done+' of '+info.total+' steps complete';
 const journey=document.querySelector('#guide-journey-progress');if(journey)journey.textContent=info.done+'/'+info.total;
 for(const phase of Guide.phases){const members=Guide.steps.filter(s=>s.phase===phase.id),count=members.filter(s=>Guide.isDone(s,state,sled)).length,caption=document.querySelector(`[data-guide-phase="${phase.id}"]>summary small`);if(caption)caption.textContent=count+' of '+members.length+' complete';}
 for(const item of Guide.steps){const button=document.querySelector(`.guide-journey-steps [data-guide-step="${item.id}"]`),caption=document.querySelector(`.guide-journey-steps [data-guide-step="${item.id}"] small`),done=Guide.isDone(item,state,sled);if(caption)caption.textContent=guideStepStatus(item,sled);if(button){button.classList.toggle('done',done);const dot=button.querySelector('.guide-step-dot');if(dot)dot.textContent=done?'✓':Guide.blockers(item,state,sled).length?'·':String(Guide.steps.indexOf(item)+1);}}
 const note=document.querySelector('#guide-completion-note');if(note)note.textContent=Guide.isDone(step,state,sled)?'✓ This step is recorded complete. Changing a finding reopens it for review.':'Completing a step checks the required findings. Saving a draft keeps it open.';
}
function focusGuideTask(){document.querySelector('#guide-task-title')?.focus({preventScroll:true});document.querySelector('#guide-workbench')?.scrollIntoView?.({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function openGuide(sled,id=''){guideSled=['early','eight'].includes(sled)?sled:'early';guideState();guideStepId=id||Guide.summary(state,guideSled).next?.id||Guide.steps[0].id;guideErrors=[];navigate('guide');}
function guidePurchaseErrors(p,status){guideState();return Guide.purchaseIssues(state,p,status);}
function showPurchaseGate(p,errors){openGuide(p.sled);guideErrors=errors.map(message=>({message}));render('guide');toast('Order is not ready: '+errors[0]);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-guide-map')){guideMapOpen=!guideMapOpen;const map=document.querySelector('.guide-journey');map.dataset.expanded=String(guideMapOpen);b.setAttribute('aria-expanded',String(guideMapOpen));b.querySelector('span:last-child').textContent=guideMapOpen?'−':'＋';return;}if(b.hasAttribute('data-guide-focus')){document.querySelector('#g-'+b.dataset.guideFocus)?.focus();return;}if(b.hasAttribute('data-guide-step')){guideStepId=b.dataset.guideStep;guideErrors=[];guideMapOpen=false;render('guide');focusGuideTask();return;}if(b.hasAttribute('data-guide-sled')){openGuide(b.dataset.guideSled);return;}if(b.hasAttribute('data-guide-upload')){guideSled=b.dataset.guideUpload;selectedSled=guideSled;openEditor('photo');const select=document.querySelector('#f-sled');if(select)select.value=guideSled;return;}if(b.dataset.guideAction)saveGuide(b.dataset.guideAction);});
document.addEventListener('submit',e=>{if(e.target.id==='guide-form'){e.preventDefault();saveGuide('complete');}});
function guideInput(e){
 if(!canEdit()||!e.target.closest||!e.target.closest('#guide-form')||e.target.closest('fieldset')?.disabled)return;
 if(!saveGuide('draft',true))return;
 const found=guideFormData();if(!found)return;
 if(e.target.matches('[data-guide-field]')){
  const data=found.data;
  document.querySelectorAll('[data-guide-when]').forEach(x=>x.hidden=data[x.dataset.guideWhen]!==x.dataset.guideEquals);
  const field=found.step.fields.find(f=>f.id===e.target.name);
  if(field?.type==='photo'){
   const preview=document.querySelector(`[data-guide-preview="${field.id}"]`);if(preview)preview.innerHTML=guidePhotoPreview(field,data[field.id],found.sled);
  }
  const progress=document.querySelector('#guide-task-progress');if(progress)progress.innerHTML=guideTaskProgress(found.step,{data});
  e.target.removeAttribute('aria-invalid');
  refreshGuideProgress(found.step,found.sled);
 }
}
document.addEventListener('input',guideInput);document.addEventListener('change',guideInput);
